#!/usr/bin/env python3
"""Build the image-led island guides from credited editorial data."""
import json,html
from urllib.parse import quote
from pathlib import Path
R=Path(__file__).resolve().parent.parent
D=json.loads((R/'data/island-guides.json').read_text()); O=R/'public/islands'; O.mkdir(exist_ok=True)
def e(s):return html.escape(str(s),quote=True)
CSS='''@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Fraunces:opsz,wght@9..144,400;9..144,500&family=JetBrains+Mono:wght@400;500&display=swap');
:root{--bg:#0B0B0F;--panel:#14141A;--ivory:#F0EEE9;--muted:#b4b3be;--gold:#C9A84C;--line:#34323b;--sans:Inter,system-ui,sans-serif;--serif:Fraunces,Georgia,serif;--mono:'JetBrains Mono',monospace}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ivory);font:16px/1.65 var(--sans)}a{color:inherit;text-underline-offset:4px}a:hover{color:var(--gold)}a:focus-visible,button:focus-visible{outline:3px solid var(--gold);outline-offset:5px}header{max-width:1376px;padding:24px 36px;margin:auto;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);gap:20px}.brand{display:flex;align-items:center;gap:12px;text-decoration:none;font:20px var(--serif)}.brand img{width:36px;height:36px;border-radius:50%}nav{display:flex;gap:23px;flex-wrap:wrap;font-size:13px;color:var(--muted)}nav a{text-decoration:none}main{max-width:1376px;margin:auto;padding:0 36px}.eyebrow{font:11px/1.7 var(--mono);text-transform:uppercase;letter-spacing:.15em;color:var(--gold)}.hero{padding:60px 0 54px;display:grid;grid-template-columns:.9fr 1.15fr;gap:50px;align-items:center}h1{font:clamp(54px,7vw,96px)/1.02 var(--serif);letter-spacing:-.045em;margin:20px 0 25px}h2{font:clamp(30px,4vw,48px)/1.15 var(--serif);letter-spacing:-.025em;margin:12px 0 18px}h3{font:25px/1.2 var(--serif);margin:8px 0 14px}p{color:var(--muted);margin:0 0 22px}.lede{font-size:18px;max-width:590px}.hero figure{margin:0}.hero img{width:100%;height:510px;object-fit:cover;border-radius:14px}.credit{font-size:11px;color:var(--muted);padding:10px 0;line-height:1.6}.credit a{color:var(--muted)}.btn{display:inline-block;text-decoration:none;border:1px solid var(--gold);padding:11px 18px;border-radius:6px;font-size:13px;margin:8px 8px 0 0;color:var(--gold)}.btn.solid{background:var(--gold);color:var(--bg)}section{padding:48px 0;border-top:1px solid var(--line);scroll-margin-top:20px}.section-top{display:flex;align-items:end;justify-content:space-between;gap:30px}.section-top p{max-width:530px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.photo{margin:0;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--panel)}.photo .picture{display:block;background:#09090d}.photo img{width:100%;height:275px;object-fit:cover;display:block}.photo figcaption{padding:22px}.photo .credit{border-top:1px solid var(--line);margin-top:20px;padding-bottom:0}.photo p{font-size:14px;margin-bottom:0}.filters{display:flex;gap:9px;flex-wrap:wrap;margin:20px 0 28px}.filters[hidden]{display:none}button{border:1px solid #585360;color:var(--ivory);background:transparent;border-radius:30px;padding:10px 17px;cursor:pointer;font:13px var(--sans)}button[aria-pressed=true]{background:var(--gold);border-color:var(--gold);color:var(--bg)}[hidden]{display:none!important}.comparison{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.comparison article{padding:25px 0}.comparison p{font-size:15px}.film-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.film{background:var(--panel);border-radius:14px;overflow:hidden;border:1px solid var(--line)}.film img{width:100%;aspect-ratio:16/9;object-fit:cover;display:block}.film .body{padding:22px}.film h3{font-size:24px}.film p{font-size:14px}.film .eyebrow{font-size:10px}.film .body>a{color:var(--gold);font-size:14px}.island-pair{display:grid;grid-template-columns:1fr 1fr;gap:28px}.island-pair a{text-decoration:none;position:relative;border-radius:14px;overflow:hidden;min-height:440px;display:flex;align-items:end;background:#14141A}.island-pair img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.island-pair .overlay{position:absolute;inset:0;background:linear-gradient(transparent 10%,#000e)}.island-pair .body{z-index:1;padding:32px;position:relative}.island-pair h2{font-size:52px}.island-pair p{color:#eee;max-width:500px}.sources{columns:2;list-style:none;padding:0}.sources li{break-inside:avoid;margin:0 0 14px;font-size:14px;color:var(--muted)}.crosslink{background:var(--panel);padding:30px;border-radius:14px;margin-top:28px}.crosslink a{color:var(--gold)}footer{max-width:1376px;margin:auto;padding:36px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}.note{font-size:13px;max-width:900px}.skip{position:absolute;top:-100px}.skip:focus{top:0;background:#111;padding:14px;z-index:9}@media(max-width:950px){.grid,.film-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.hero{gap:26px}.hero img{height:430px}.comparison{grid-template-columns:1fr}.comparison article{padding:10px 0}}@media(max-width:650px){header{padding:20px;align-items:start}.brand{font-size:17px;white-space:nowrap}nav{gap:10px;justify-content:end;font-size:11px}main{padding:0 20px}.hero{display:flex;flex-direction:column;padding:35px 0;gap:30px;align-items:stretch}.hero img{height:340px}.grid,.film-grid,.island-pair{grid-template-columns:1fr}.section-top{display:block}.photo img{height:300px}.sources{columns:1}.island-pair a{min-height:380px}footer{padding:26px 20px}h1{font-size:64px}}
'''
(R/'public/assets/island-guides.css').write_text(CSS)
(R/'public/assets/js/island-guides.js').write_text('''document.querySelectorAll('[data-gallery]').forEach(g=>{const buttons=g.querySelectorAll('button[data-filter]');g.querySelector('.filters').hidden=false;buttons.forEach(b=>b.addEventListener('click',()=>{buttons.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));g.querySelectorAll('[data-category]').forEach(x=>x.hidden=b.dataset.filter!=='All'&&x.dataset.category!==b.dataset.filter);const n=[...g.querySelectorAll('[data-category]')].filter(x=>!x.hidden).length;g.querySelector('[role=status]').textContent=n+' photographs shown';}));});''')
def credit(p):return f'<div class="credit">{e(p["author"])} · <a href="{e(p["license_url"])}">{e(p["license"])}</a> · <a href="{e(p["source"])}">Wikimedia Commons ↗</a></div>'
def page(slug,title,desc,body,image):
 path='/islands/'+(slug+'/' if slug else '')
 text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | The Ancient Atlas</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="https://theancientatlas.com{path}"><meta property="og:type" content="article"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="https://theancientatlas.com{path}"><meta property="og:image" content="https://theancientatlas.com{image}"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#0B0B0F"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/assets/island-guides.css"><script defer src="/assets/js/island-guides.js"></script><script defer src="/assets/js/analytics.js"></script><script data-goatcounter="https://ancientatlas.goatcounter.com/count" async src="//gc.zgo.at/count.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/"><img src="/icon-256.png" alt="">The Ancient Atlas</a><nav aria-label="Main navigation"><a href="/photos/">Photographs</a><a href="/islands/">Island guides</a><a href="/sites/">The map index</a><a href="/creators/">Creators</a></nav></header><main id="main">{body}</main><footer>Photographs remain the work of their credited authors. Images are resized and converted to WebP; some previews crop to fit. Open a photograph to see the complete image. Licence and original-source links accompany every photograph.<br><a href="/islands/image-credits.json">Full photo credits</a> · <a href="/creators/">Explore the creators</a> · <a href="/contact.html">Suggest a correction</a></footer></body></html>'''
 out=O/slug if slug else O;out.mkdir(exist_ok=True);(out/'index.html').write_text(text)
def hero(k,title,sub,desc,photo):return f'<div class="hero"><div><div class="eyebrow">Island field guides · {k}</div><h1>{title}</h1><h2>{sub}</h2><p class="lede">{desc}</p><a class="btn solid" href="#photographs">Explore the photographs ↓</a><a class="btn" href="#comparisons">Compare the islands</a></div><figure><a href="{photo["image"]}"><img src="{photo["image"]}" alt="{e(photo["site"]+": "+photo["description"])}" fetchpriority="high"></a><figcaption>{credit(photo)}</figcaption></figure></div>'
def gallery(photos):
 categories=list(dict.fromkeys(p['category'] for p in photos));s='<section id="photographs" data-gallery><div class="section-top"><div><div class="eyebrow">Look closer</div><h2>Read the stone.</h2></div><p>Start with the whole structure. Then follow the entrances, stone courses and carved details.</p></div><div class="filters" hidden aria-label="Photograph categories">'
 for cat in ['All']+categories:s+=f'<button data-filter="{e(cat)}" aria-pressed="{str(cat=="All").lower()}">{e(cat)}</button>'
 s+='</div><p class="note" role="status" aria-live="polite">'+str(len(photos))+' photographs shown</p><div class="grid">'
 for p in photos:s+=f'<figure class="photo" data-category="{e(p["category"])}"><a class="picture" href="{p["image"]}" aria-label="View complete photograph: {e(p["title"])}"><img src="{p["image"]}" alt="{e(p["site"]+": "+p["description"])}" loading="lazy"></a><figcaption><div class="eyebrow">{e(p["site"])}</div><h3>{e(p["title"])}</h3><p>{e(p["description"])}</p>{credit(p)}</figcaption></figure>'
 return s+'</div></section>'
def comparisons():return '''<section id="comparisons"><div class="eyebrow">Across the Strait of Bonifacio</div><h2>Two islands. Related questions.</h2><p>Corsica lies directly north of Sardinia. Comparing individual features helps the eye; each monument still needs its own history.</p><div class="comparison"><article><div class="eyebrow">Towers and stonework</div><h3>Torre and nuraghi</h3><p>Corsican torre and Sardinian nuraghi share circular plans and corbelled stone roofing. The size and development of their complexes differ. Compare rooms, entrances and walls before drawing conclusions about purpose.</p></article><article><div class="eyebrow">Megalithic burial</div><h3>Large stones, different tombs</h3><p>Funtanaccia is a dolmen with upright supports and a capstone. Sardinia’s Giants’ Tombs have their own distinctive form. The comparison concerns large-stone construction and collective burial.</p></article><article><div class="eyebrow">What this survey has not matched</div><h3>Keep the differences visible</h3><p>No close Corsican counterpart to Santa Cristina’s built sacred well or Sardinia’s decorated Domus de Janas was verified in this image survey. Natural granite shelters are a different feature.</p></article></div></section>'''
def orii():
 p=D['orii'][0]
 return '<section id="orii"><div class="hero" style="padding:0"><figure><a href="'+p['image']+'"><img src="'+p['image']+'" alt="Oriu di i Canni: pointed natural granite roof above a stone doorway" loading="lazy" style="object-fit:contain;height:auto"></a><figcaption>'+credit(p)+'</figcaption></figure><div><div class="eyebrow">Corsica’s orii · rock shelters</div><h2>A house inside a rock.</h2><p>Nature hollowed the granite. People added a doorway.</p><p class="note">Oriu di i Canni is private and currently closed to visitors.</p><a class="btn" href="/?site=Oriu%20di%20i%20Canni">Canni on the map →</a><a class="btn" href="/?site=Oriu%20di%20Cubia">Find Cubia →</a><a class="btn" href="/?site=Oriu%20di%20Grussettu">Find Grussettu →</a><p style="margin-top:22px"><a href="https://www.youtube.com/watch?v=3_Km-hwFPYA&amp;t=220s">Step beneath Grussettu with Schwendi Colours ↗</a></p></div></div></section>'

def corsica_films():
 data=json.loads((R/'data/corsica-films.json').read_text())
 cards=[]
 for f in data['films']:
  url='https://www.youtube.com/watch?v='+f['id']
  cards.append(f'<article><a href="{url}"><img src="https://i.ytimg.com/vi/{f["id"]}/hqdefault.jpg" alt="{e(f["title"])}" loading="lazy" style="width:100%;max-width:640px;aspect-ratio:16/9;object-fit:cover;border-radius:10px"></a><div class="eyebrow">{e(f.get("format", "On-location film"))} · {f["duration"]//60}:{f["duration"]%60:02d} · {e(f["area"])}</div><h3>{e(f["title"])}</h3><p>{e(f["note"])}</p><p>By <a href="{e(f["channel_url"])}">{e(f["creator"])}</a></p><a class="btn" href="{url}">Watch the original film ↗</a><a class="btn" href="{e(f["channel_url"])}">Explore {e(f["creator"])} ↗</a></article>')
 return '<section id="films"><div class="eyebrow">Through the creators’ eyes</div><h2>Walk the ground in Corsica.</h2><div class="grid">'+''.join(cards)+'</div></section>'

def films():
 vids=[('q0YNkMIt3BY','Original field documentary · Stone Riddles','Documentary Stone Riddles II  - Archaeological Treasures of Sardinia - full version','Mirko and Deborah’s extended exploration of Sardinia. Follow the original footage and the creators behind it.','https://www.youtube.com/watch?v=q0YNkMIt3BY'),('Xq_YM0s4nzA','Ancient Atlas · conversation with Jeff & Gerald','Sardinia Has 7,000 Stone Towers. We Had Never Heard of Them.','An 8-minute conversation, with source footage by Stone Riddles and credited Commons photographs.','https://www.youtube.com/watch?v=Xq_YM0s4nzA'),('KBu3J8v7kfU','On-location visit · Haswell Travelled','Nuraghe from Ancient Civilization - Su Nuraxi di Barumini, Sardinia, Italy 4K','A separate creator’s visit to Su Nuraxi. Return to the mapped site for more perspectives.','https://www.youtube.com/watch?v=KBu3J8v7kfU')]
 s='<section id="watch"><div class="section-top"><div><div class="eyebrow">Go further with the people filming it</div><h2>Three ways into Sardinia.</h2></div><p>Original explorations, a shared reaction and another view on the ground. Every film leads to its own creator.</p></div><div class="film-grid">'
 for id,label,title,desc,url in vids:s+=f'<article class="film"><a href="{url}"><img src="https://i.ytimg.com/vi/{id}/hqdefault.jpg" alt="{e(title)}" loading="lazy"></a><div class="body"><div class="eyebrow">{e(label)}</div><h3><a href="{url}">{e(title)}</a></h3><p>{e(desc)}</p><a href="{url}">Watch the film ↗</a></div></article>'
 return s+'''</div><div class="crosslink">Follow the original creators: <a href="https://www.youtube.com/@StoneRiddles">Stone Riddles ↗</a> · <a href="https://www.youtube.com/@HaswellTravelled">Haswell Travelled ↗</a><br><a href="/sites/sardinia-nuraghi-su-nuraxi.html">Explore Su Nuraxi and its other films →</a> · <a href="/creators/">Discover more creators →</a></div></section>'''
def refs(corsica):
 src=[('Monacia orii · municipal heritage trail','https://monacia-aullene.fr/le-sentier-du-patrimoine/'),('Cucuruzzu–Capula · Collectivité de Corse','https://www.isula.corsica/patrimoine/Le-site-archeologique-de-Cucuruzzu-Capula_a12.html'),('Cauria · Collectivité de Corse','https://www.isula.corsica/patrimoine/Les-sites-archeologiques-du-pianu-de-Cauria_a11.html'),('Torre and corbelled construction · Filitosa','https://www.filitosa.fr/en/prehistoric-site/architectures/'),('Su Nuraxi · UNESCO','https://whc.unesco.org/en/list/833/'),('Domus de Janas · UNESCO','https://whc.unesco.org/en/list/1730/')]
 return '<section><div class="eyebrow">Sources and reading</div><h2>Follow the evidence.</h2><ul class="sources">'+''.join(f'<li><a href="{u}">{e(t)} ↗</a></li>' for t,u in src)+'</ul><p class="note">Image-led research guide, reviewed 26 October 2026. The comparison follows the monument groups in Stone Riddles II. It is not a complete archaeological inventory of either island.</p></section>'
def mapped_places(island):
 spec=json.loads((R/'data/island-map-review.json').read_text())
 names=[x['site']['n'] for x in spec['new_sites'] if x['country']==('France' if island=='corsica' else 'Italy')]
 names += ['Filitosa (Corsica)'] if island=='corsica' else ['Nuraghe Losa','Nuraghe Arrubiu','Nuraghe Santu Antine','Sardinia Nuraghi (Su Nuraxi)','San Andrea Priù','Sacred Well of Sa Testa']
 chapters={x['site']:x['seconds'] for x in spec['documentary']['placements']}
 text='<section id="mapped-sites"><div class="eyebrow">On the ground</div><h2>Find the monuments.</h2><div class="grid">'
 for n in names:
  text+=f'<div><a href="/?site={quote(n,safe="")}">{e(n)}</a>'
  if n in chapters:
   t=chapters[n];stamp=f'{t//3600}:{t%3600//60:02d}:{t%60:02d}' if t>=3600 else f'{t//60}:{t%60:02d}'
   text+=f'<br><a class="credit" href="https://www.youtube.com/watch?v=q0YNkMIt3BY&amp;t={t}s">Stone Riddles · {stamp} ↗</a>'
  text+='</div>'
 text+='</div>'
 if island=='sardinia':text+='<p style="margin-top:28px"><a href="/creators/sardinia">More site visits, including Earth Explorer at Santa Cristina →</a></p>'
 else:text+='<p class="note" style="margin-top:28px">Open a place for its films. Cauria coverage includes time-lapse visits.</p>'
 return text+'</section>'
c=D['corsica'];s=D['sardinia']
body=hero('01 · Corsica','Corsica.','Granite, gathered into monuments.','Giant blocks, narrow passages and human figures carved in stone. Explore the island immediately north of Sardinia through twelve photographs.',c[0])+gallery(c)+orii()+corsica_films()+mapped_places('corsica')+comparisons()+'''<div class="crosslink"><div class="eyebrow">The neighbouring island</div><h3>Continue south to Sardinia.</h3><p>Nuragic towers and the sacred well of Santa Cristina bring the comparison into focus.</p><a href="/islands/sardinia/">Explore Sardinia’s photographs and films →</a> · <a href="/sites/filitosa-corsica.html">Filitosa in the Atlas →</a></div>'''+refs(True)
page('corsica','Corsica: megaliths, towers and carved figures','A visual guide to Corsica’s torre, massive masonry, dolmens and statue-menhirs, with careful comparisons to Sardinia.',body,c[0]['image'])
body=hero('02 · Sardinia','Sardinia.','Follow the stone inward.','From towers rising over a village to stairs descending into a sacred well. Six photographs open the way into the architecture, followed by films from the people exploring it.',s[4])+gallery(s)+mapped_places('sardinia')+films()+comparisons()+'''<div class="crosslink"><div class="eyebrow">Across the strait</div><h3>What carries over to Corsica?</h3><p>Compare tower rooms, dry-stone passages, dolmens and carved standing stones.</p><a href="/islands/corsica/">Explore Corsica →</a></div>'''+refs(False)
page('sardinia','Sardinia: nuraghi, sacred wells and films','Explore Sardinia’s stone towers and Santa Cristina in photographs, then watch Stone Riddles, Jeff and Gerald, and other creators.',body,s[4]['image'])
body='''<section style="border:0;padding-top:50px"><div class="eyebrow">The Ancient Atlas · Island field guides</div><h1>Across the strait.</h1><p class="lede">Corsica and Sardinia. Two neighbouring islands, read through their stonework. Start with the photographs, compare the features, then follow the people filming the places.</p></section><div class="island-pair">'''
for slug,name,desc,p in [('corsica','Corsica','Towers, massive granite, dolmens and carved human figures.',c[0]),('sardinia','Sardinia','Nuraghi, a sacred well, and three ways into the films.',s[4])]:body+=f'<a href="/islands/{slug}/"><img src="{p["image"]}" alt="{e(p["site"])}"><span class="overlay"></span><div class="body"><div class="eyebrow">Island field guide</div><h2>{name}</h2><p>{desc}</p><span>Explore {name} →</span></div></a>'
body+='</div><section><div class="eyebrow">A shared map, many voices</div><h2>The place comes first.</h2><p>Photographs show what to notice. Original filmmakers take you onto the ground. Ancient Atlas conversations sit alongside that work, with the source creators named and linked.</p><a class="btn" href="/creators/">Meet the creators →</a><a class="btn" href="/sites/">Browse every mapped place →</a></section>'
page('','Corsica and Sardinia: island field guides','Photographic guides to the ancient stonework of Corsica and Sardinia, with source credits and films from independent creators.',body,c[0]['image'])
(O/'image-credits.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
print('Built /islands/, /islands/corsica/ and /islands/sardinia/')
